    key_positions = {}  # Track first occurrence position of each key
    for i, row in enumerate(validated):
        key = row["key"]
        value = row["value"]
        if key not in key_positions:
            # First occurrence: add to keys list and record position
            key_positions[key] = len(keys)
            keys.append(key)
            values.append(value)
        else:
            # Already seen: update value (last occurrence wins)
            values[key_positions[key]] = value
    return {"keys": keys, "values": values}

