import re
from schema import And, Or, Schema, SchemaError


def build_catalog(rows):
    name = And(str, lambda value: re.fullmatch(r"[a-z]+", value) is not None)
    try:
        validated = Schema([{"key": name, "value": Or(str, int, bool, type(None))}]).validate(rows)
    except SchemaError:
        return None

    # Track first occurrence order and last occurrence values
    keys_order = []  # keys in order of first occurrence
    last_values = {}  # last value seen for each key

    for row in validated:
        key = row["key"]
        value = row["value"]

        # If this is the first time we see this key, add it to the order
        if key not in keys_order:
            keys_order.append(key)

        # Always update the last value for this key
        last_values[key] = value

    return {"keys": keys_order, "values": [last_values[k] for k in keys_order]}

